lemma finMapToEquiv_symm_eq {f1 : Fin n → Fin m} {f2 : Fin m → Fin n}
    {h : ∀ x, f1 (f2 x) = x} {h' : ∀ x, f2 (f1 x) = x} :
    (finMapToEquiv f1 f2 h h').symm = finMapToEquiv f2 f1 h' h

lemma involutionAddEquiv_none_succ {n : ℕ}
    {f : {f : Fin n.succ → Fin n.succ // Function.Involutive f}}
    (h : involutionAddEquiv (involutionCons n f).1 (involutionCons n f).2 = none)
    (x : Fin n) : f.1 x.succ = x.succ ↔ (involutionCons n f).1.1 x = x

lemma involutionCons_ext {n : ℕ} {f1 f2 : (f : {f : Fin n → Fin n // Function.Involutive f}) ×
    {i : Option (Fin n) // ∀ (h : i.isSome), f.1 (Option.get i h) = (Option.get i h)}}
    (h1 : f1.1 = f2.1) (h2 : f1.2 = Equiv.subtypeEquivRight (by rw [h1]; simp) f2.2) : f1 = f2

lemma involutionNoFixed_card_succ {n : ℕ} :
    Fintype.card
    {f : Fin n.succ.succ → Fin n.succ.succ // Function.Involutive f ∧ (∀ i, f i ≠ i)}
    = n.succ *
    Fintype.card {f : Fin n → Fin n // Function.Involutive f ∧ (∀ i, f i ≠ i)}

@[ext]
lemma eq_of_apply {d} {p q : Space d}
    (h : ∀ i : Fin d, p i = q i) : p = q

lemma figureOfMerit_le_of_le (M : ThermoelectricMaterial) {κl' T : ℝ}
    (hpos : 0 < κl') (h : M.κl ≤ κl') (hT : 0 ≤ T) :
    figureOfMerit { M with κl := κl', κl_pos := hpos } T ≤ M.figureOfMerit T

lemma figureOfMerit_pos {M : ThermoelectricMaterial} {T : ℝ}
    (hS : M.S ≠ 0) (hT : 0 < T) :
    0 < M.figureOfMerit T

lemma gradient_comp_coord {ι : Type*} [Fintype ι] [DecidableEq ι] {f : ℝ → ℝ} {f' : ℝ}
    (i : ι) (x : EuclideanSpace ℝ ι) (hf : HasDerivAt f f' (x i)) :
    gradient (fun y : EuclideanSpace ℝ ι => f (y i)) x = f' • EuclideanSpace.single i 1

lemma induction_tmul {f g : ((⨂[R] i : ι1, s1 i) ⊗[R] (⨂[R] i : ι2, s2 i)) →ₗ[R] M}
    (h : ∀ p q, f (PiTensorProduct.tprod R p ⊗ₜ[R] PiTensorProduct.tprod R q)
    = g (PiTensorProduct.tprod R p ⊗ₜ[R] PiTensorProduct.tprod R q)) : f = g

lemma scaleUnit_val_eq_scaleUnit_val_of_dim_eq {d1 d2 : Dimension LTMCTDimensionBase} {M : Type}
    [MulAction ℝ≥0 M]
    {u1 u2 : LTMCTUnitChoices} {m1 : WithDim d1 M} {m2 : WithDim d2 M}
    (h : d1 = d2 := by ext <;> {simp; try ring}) :
    (scaleUnit u1 u2 m1).val = (scaleUnit u1 u2 m2).val ↔ m1.val = m2.val

lemma withDim_hMul_val {B : Type} [DimensionBasis B] {d1 d2 : Dimension B}
    (m1 : WithDim d1 ℝ) (m2 : WithDim d2 ℝ) :
    (m1 * m2).val = m1.val * m2.val

theorem HasFiniteMultiplicity.finiteDimensional_range {p : H →L[ℂ] H}
    (hp : HasFiniteMultiplicity p) :
    FiniteDimensional ℂ (LinearMap.range p.toLinearMap)

theorem summable_inner_abs_of_hilbertBasis {T : H →L[ℂ] H} (h : IsTraceClass T) {w : Set H}
    (b : HilbertBasis w ℂ H) :
    Summable (fun i => (⟪b i, CFC.abs T (b i)⟫_ℂ).re)

theorem traceNorm_eq_of_hilbertBasis {T : H →L[ℂ] H} (h : IsTraceClass T) {w : Set H}
    (b : HilbertBasis w ℂ H) :
    traceNorm T h = ∑' i, (⟪b i, CFC.abs T (b i)⟫_ℂ).re

lemma simpleIntegral_norm_le (f : SimpleFunc α ℂ) (x : H) {C : ℝ}
    (hC : 0 ≤ C) (hCf : ∀ z ∈ f.range, ‖z‖ ≤ C) :
    ‖simpleIntegral μS f x‖ ≤ C * ‖x‖

lemma simpleIntegral_toCLM_cauchySeq [Nonempty α] {f : α → ℂ} {s : ℕ → SimpleFunc α ℂ}
    (hs : ∀ ε > 0, ∃ N, ∀ n ≥ N, ∀ x, ‖s n x - f x‖ < ε) :
    CauchySeq (fun n => ContinuousLinearMapWOT.toCLM (simpleIntegral μS (s n)))

lemma simpleIntegral_toCLM_norm_le (f : SimpleFunc α ℂ) {C : ℝ}
    (hC : 0 ≤ C) (hCf : ∀ z ∈ f.range, ‖z‖ ≤ C) :
    ‖ContinuousLinearMapWOT.toCLM (simpleIntegral μS f)‖ ≤ C

lemma integral_eq_zero_of_support_disjoint {f : CompactlySupportedContinuousMap X ℝ}
    {S : Set X} (hS_meas : MeasurableSet S) (hS : ∀ x ∈ S, f x = 0) :
    ∫ x, f x ∂(Λ.measure.restrict S) = 0

lemma measure_ext {Λ₁ Λ₂ : CompactPositiveFunctional (X := X)}
    (hΛ : ∀ f, Λ₁.functional f = Λ₂.functional f) :
    Λ₁.measure = Λ₂.measure

lemma polarizedCfcScalarMeasure_norm_le (x y : H) {S : Set (spectrum ℂ U)}
    (hS : MeasurableSet S) :
    ‖polarizedCfcScalarMeasure (hU := hU) U x y S‖ ≤ ‖x‖ ^ 2 + ‖y‖ ^ 2

lemma polarizedCfcScalarMeasure_norm_le_mul (x y : H) {S : Set (spectrum ℂ U)}
    (hS : MeasurableSet S) :
    ‖polarizedCfcScalarMeasure (hU := hU) U x y S‖ ≤ 2 * ‖x‖ * ‖y‖

theorem sSup_image_eq_sSup_image_closure {f : β → α}
  (hS : IsCompact (closure S)) (hf : Continuous f) :
    sSup (f '' S) = sSup (f '' closure S)

theorem ENNReal.tendsto_toReal_iff_of_eventually_ne_top
  {ι} {fi : Filter ι} {f : ι → ℝ≥0∞} (hf : ∀ᶠ i in fi, f i ≠ ∞) {x : ℝ≥0∞}
    (hx : x ≠ ∞) : Tendsto (fun n => (f n).toReal) fi (𝓝 x.toReal) ↔ Tendsto f fi (𝓝 x)

theorem operatorConvex_continuousOn_spectrum_union {f : ℝ → ℝ}
    (hf : OperatorConvex (ℋ := ℋ) f) (A B : L ℋ) :
    ContinuousOn f (spectrum ℝ A ∪ spectrum ℝ B)

theorem csInf_mul_nonneg {s t : Set ℝ}
  (hs₀ : s.Nonempty) (hs₁ : ∀ x ∈ s, 0 ≤ x) (ht₀ : t.Nonempty) (ht₁ : ∀ x ∈ t, 0 ≤ x) :
    sInf (s * t) = sInf s * sInf t
